import type { Lang } from '@/seo/langs';
import generated from './gallery.generated.json';

/**
 * Real work photos and videos. You do NOT edit this file: drop files in public/gallery/ (see the README there).
 * scripts/gallery.mjs turns that folder into gallery.generated.json before every `npm run dev` / `npm run build`.
 * The gallery section (and its menu link) only appears when the folder contains at least one file.
 */
export type GalleryItem = {
  type: 'image' | 'video';
  src: string;
  /** Preview picture of a video (optional). */
  poster?: string;
  /** Real city of the job, shown on the picture. */
  city: Record<Lang, string>;
  alt: Record<Lang, string>;
  caption: Record<Lang, string>;
};

export const gallery = generated as GalleryItem[];
